import ipaddress
rules = [
  ("allow", "10.1.0.0/16", "10.9.0.5", 443),
  ("deny",  "any",         "10.9.0.0/24", "any"),
  ("allow", "any",         "any", 80),
]
def match(net, ip):
    return net == "any" or ipaddress.ip_address(ip) in ipaddress.ip_network(net)
def judge(src, dst, port):
    for i,(act,s,d,p) in enumerate(rules,1):
        if match(s,src) and match(d,dst) and p in ("any",port):
            return i,act
    return 0,"deny(기본)"
for t in [("10.1.2.3","10.9.0.5",443),("10.1.2.3","10.9.0.6",443),("192.168.0.9","10.9.0.5",443),("192.168.0.9","8.8.8.8",80)]:
    print(t, judge(*t))

from collections import defaultdict
log = [("10.1.2.3", p, t) for t, p in enumerate([22,80,443,3306,5432,6379,8080,9200,27017,22])]
log += [("10.1.5.5", 443, t*20) for t in range(5)]
by = defaultdict(list)
for src, port, t in log:
    by[src].append((t, port))
for src, ev in by.items():
    ports = {p for t, p in ev if ev[-1][0]-t <= 30}
    print(src, "서로 다른 포트", len(ports), "→", "스캔 의심(ATT&CK T1046)" if len(ports) >= 8 else "정상 범위")
